import 'dart:io'; import 'package:image/image.dart' as img; void main() { final file = File('assets/images/revive_logo.png'); final bytes = file.readAsBytesSync(); final image = img.decodeImage(bytes); if (image == null) return; for (var p in image) { if (p.r > 230 && p.g > 230 && p.b > 230) { p.a = 0; } } file.writeAsBytesSync(img.encodePng(image)); print('Transparency Applied!'); }
